def carry(old, new, title, intro, urlfix):
    t=open(old).read().split('\n')
    out=[title,'',intro]
    body=t[2:]
    for l in body:
        for k,u in urlfix.items():
            if l.startswith(k) and 'http' not in l: l=l+' — '+u
        out.append(l)
    return out
